  "settings.clearLibraryV2Hint": "Czyści indeks (utwory, albumy, wykonawców). Wraz z nim przepadają: zawartość playlist, oceny, zakładki, ulubione, ręcznie złożone zestawy pudełkowe i edycje albumów. Żaden plik muzyczny nie jest usuwany. Tuż przed operacją wykonywana jest kopia zapasowa bazy danych. Analiza przywraca tylko utwory. Aby odświeżyć bibliotekę, uruchom zamiast tego „pełna analiza”: zachowuje ona zestawy pudełkowe i edycje albumów.",
