  "renderer.wav24Hint": "Przesyłaj prawdziwy WAV 24-bitowy. Oferowane domyślnie; odrzucane tylko wtedy, gdy test wykrywania dowodzi, że ten renderer nie deklaruje ani audio/L24, ani audio/wav.",
  "renderer.depthCapNotRate": "Uwaga: ograniczenie głębi bitowej nie ogranicza częstotliwości próbkowania. Plik 96 kHz/24 bity staje się plikiem 96 kHz/16 bitów — nadal 96 kHz. Jeśli Twój renderer obsługuje maksymalnie 48 kHz, ustaw także „Maks. częstotliwość”.",
  "renderer.flacAndWavSplitBySource": "„Wymuś WAV” dotyczy tylko źródeł innych niż FLAC (ALAC, AAC…) — omija dekoder ALAC renderera. Twoje pliki FLAC nadal są przesyłane jako natywny FLAC.",
  "renderer.wav24Unproven": "Żaden test wykrywania nie zakończył się jeszcze powodzeniem: 24 bity pozostają dostępne, ale nic nie potwierdza, że to urządzenie potrafi je odtworzyć. Naciśnij „Sprawdź” powyżej.",
  "renderer.wav24Refused": "Test wykrywania wykazał: to urządzenie nie deklaruje ani audio/L24, ani audio/wav. 24 bity pozostają zablokowane — przesłanie ich skutkowałoby odtworzeniem ciszy.",
  "renderer.startDelay": "Opóźnienie startu",
  "renderer.startDelayHint": "Pauza przed rozpoczęciem odtwarzania, aby wzmacniacz DLNA zdążył zbuforować dane (pomaga, gdy pierwsze sekundy się zacinają). 0 = wartość domyślna.",
