  "renderer.probeSoapFailed": "Renderer został wykryty, ale zapytanie o możliwości nie powiodło się. Spróbuj ponownie; jeśli już odtwarza, nie ma potrzeby zmieniać ustawień sieci.",
  "renderer.saveError": "Nie udało się zapisać ustawienia.",
