  "renderer.saveConfigHint": "Te ustawienia są stosowane na urządzeniu od razu po kliknięciu. Ten przycisk dodatkowo zachowuje trwałą kopię powiązaną z tym urządzeniem, którą w każdej chwili możesz przywrócić z tego ekranu.",
