  "renderer.resetCompat": "Zresetuj zgodność",
  "renderer.resetCompatHint": "Gdy renderer odrzuci polecenie, Tune zapamiętuje formę polecenia, którą ten akceptuje, i używa jej ponownie, także po ponownym uruchomieniu. Reset sprawia, że następny utwór zacznie od pełnego polecenia.",
