  "renderer.resetCompatError": "Nie udało się zresetować zgodności.",
  "settings.dlnaCap16bitHint": "Włącz, jeśli hi-res (24-bit) nie daje dźwięku na tym rendererze, a 16-bit działa (Ruark R3). Przekodowuje do 16-bitowego FLAC zamiast wysyłać bezpośrednio 24-bit, którego renderer nie potrafi zdekodować.",
  "settings.alacPassthroughHint": "Wysyłaj ALAC bez zmian do tego renderera (bit-perfect, bez transkodowania do FLAC). Włącz tylko wtedy, gdy renderer natywnie dekoduje ALAC, w przeciwnym razie nie będzie dźwięku.",
  "settings.aacPassthroughHint": "Wysyłaj AAC bez zmian do tego renderera zamiast transkodować do FLAC. Źródło jest już stratne, więc transkodowanie nie poprawia jakości — tylko opóźnia pierwszy dźwięk. Włącz tylko wtedy, gdy renderer natywnie dekoduje AAC, w przeciwnym razie nie będzie dźwięku.",
  "settings.hqplayerHint": "Połącz Tune z HQPlayerem, aby korzystać z upsamplingu i filtrów audiofilskich. Domyślny port: 4321 (v4/v5) lub 8019 (v6).",
