  "settings.signOutConfirm": "Wylogować się z konta Mozaiklabs? Ten serwer zostanie odłączony od konta: usunięta zostanie jego kopia biblioteki online oraz udostępnienia Tune Circle, a funkcje premium wynikające z konta przestaną działać (klucz licencyjny pozostaje aktywny). Później możesz zalogować się ponownie.",
  "settings.licenseRateLimited": "Zbyt wiele prób — odczekaj minutę i spróbuj ponownie.",
  "settings.cloudComingSoon": "Chmura wkrótce na tym serwerze",
  "settings.telemetry": "Telemetria",
  "settings.telemetryHint": "Wysyłaj statystyki użycia, aby ulepszać Tune: identyfikator instancji, wersję, platformę, rozmiary biblioteki, połączone usługi i modele urządzeń.",
  "settings.telemetryOffScope": "Wyłączenie wstrzymuje także udostępnianie i pobieranie metadanych społeczności. Weryfikacja licencji działa nadal, więc Premium nigdy nie zostanie utracone.",
  "settings.communitySync": "Udostępnianie metadanych społeczności",
  "settings.communitySyncHint": "Dołącz do wzbogacania społecznościowego: rozpoznawanie MusicBrainz, gatunki i wykonawcy (kompozytor, dyrygent, wykonawcy) udostępniane między serwerami Tune. Anonimowo — nigdy Twoje pliki.",
  "settings.cloudListens": "Wysyłaj moje odsłuchy na moje konto",
  "settings.cloudListensHint": "Dodaje odsłuchy z tego serwera do strony „Moje odsłuchy” na Twoim koncie, razem z odsłuchami z innych Twoich serwerów Tune. Dla każdego odsłuchu: data, czas trwania, anonimowy identyfikator profilu, tytuł, wykonawca, album oraz, jeśli są znane, ISRC i identyfikator MusicBrainz. Nigdy ścieżki plików, adres IP ani nazwy stref. Domyślnie wyłączone.",
  "settings.cloudListensLink": "Zobacz moje odsłuchy na mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Udostępnić odsłuchy swojemu kontu mozaiklabs.fr?",
  "settings.cloudListensConsentIntro": "Tune może dodawać odsłuchy z tego serwera do Twojego konta mozaiklabs.fr. Nic nie zostanie wysłane, dopóki nie odpowiesz.",
  "settings.cloudListensConsentSentLabel": "Co jest wysyłane:",
  "settings.cloudListensConsentSent": "dla każdego odsłuchu data, czas trwania, tytuł, wykonawca, album, anonimowy identyfikator profilu oraz, jeśli są znane, identyfikatory ISRC i MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "Co nigdy nie jest wysyłane:",
  "settings.cloudListensConsentNever": "ścieżki plików, adres IP, nazwy stref i nazwy profili.",
  "settings.cloudListensConsentBenefit": "Co zyskujesz: stronę „Moje odsłuchy”, która łączy odsłuchy ze wszystkich Twoich serwerów Tune, oraz odsłuchy społeczności.",
  "settings.cloudListensConsentSettingsReminder": "Możesz zmienić zdanie w dowolnym momencie w Ustawienia › System.",
  "settings.cloudListensConsentError": "Nie udało się zapisać odpowiedzi. Spróbuj ponownie.",
  "settings.cloudListensConsentNo": "Nie",
