  "settings.communityShare": "Udostępniaj moje oceny i odsłuchy społeczności (anonimowo)",
  "settings.communityShareHint": "Niezależne od „Moich odsłuchów” i domyślnie wyłączone. Twoje oceny albumów (bez komentarza) oraz odsłuchy odebrane przez Twoje konto PO włączeniu trafiają do publicznych, anonimowych sum wyświetlanych na stronie albumu od trzech różnych osób. Dane indywidualne nigdy nie są pokazywane. Wyłączenie natychmiast usuwa Twój wkład.",
  "settings.communityMeasuresReceive": "Odbieraj wyniki analiz od społeczności",
  "settings.communityMeasuresReceiveHint": "Domyślnie wyłączone. Dla Twoich plików FLAC serwer pyta mozaiklabs.fr o ReplayGain, zakres dynamiki i odciski akustyczne zmierzone już na dokładnie tym samym sygnale przez co najmniej dwie inne instalacje. Uzupełniają one tylko to, czego brakuje: Twoje tagi i własne pomiary nigdy nie są zastępowane. Witryna otrzymuje tylko krótki prefiks, nigdy listę Twoich plików.",
  "settings.communityMeasuresContribute": "Udostępniaj moje wyniki analiz społeczności",
  "settings.communityMeasuresContributeHint": "Domyślnie wyłączone. Serwer wysyła do witryny wyłącznie pomiary wykonane samodzielnie na Twoich plikach FLAC (ReplayGain, zakres dynamiki, odcisk akustyczny), oznaczone sygnaturą ich sygnału. Nie jest wysyłana żadna ścieżka, tytuł, nazwa pliku ani konto: serwer identyfikuje się numerem instalacji. Wyłączenie usuwa to, co zostało wysłane.",
