  "zoneConfig.monoDesc": "Jeśli podłączony jest tylko jeden głośnik lub jeden kanał pozostaje niemy, wszystko, co zmiksowano wyłącznie na drugi kanał, znika: głos, gitara, czasem połowa orkiestry.",
