  "zoneConfig.channelsNetworkCeiling": "Wyjście sieciowe: wybór obowiązuje, gdy Tune dekoduje strumień – wielokanałowy utwór z biblioteki jest redukowany do wybranej liczby kanałów. Tune nigdy nie dodaje kanałów, strumień DSD przesyłany bez zmian pozostaje nietknięty, a jeśli urządzenie zgłasza mniej kanałów, decyduje urządzenie.",
