  "settings.analysisUnthrottleConfirm": "Tune nie może odczytać temperatury tego procesora: nie będzie mógł zatrzymać analiz, jeśli urządzenie się nagrzeje. Słabo wentylowane urządzenie może się przegrzać, a nawet wyłączyć. Zdjąć ograniczenie mimo to?",
