  "settings.queuePlacement": "Kolejka",
  "settings.queuePlacementHint": "Na ekranie „Teraz odtwarzane” na szerokim ekranie: gdzie otwiera się kolejka. Pod paskiem rozwija się w miejscu, kolumna z tytułami się poszerza, a strona się przewija.",
