  "settings.sidebarOrder": "Kolejność paska bocznego",
  "settings.sidebarOrderHint": "Przeciągnij pozycję lub użyj jej strzałek, aby umieścić ją w dowolnym miejscu. Odznacz ją, aby ukryć. Pozycja z poziomu Zaawansowany lub Ekspert jest widoczna tylko na tym poziomie, w wybranym miejscu. Po zmianie kolejności pasek boczny staje się jedną listą bez nagłówków grup. Ekran główny i Ustawienia pozostają zawsze widoczne; serwisy Streaming i półki Kolekcji podążają za swoją pozycją.",
