  "v2.circle.scene.loc.what": "Domyślnie wyłączone. Miasto wskazujesz samodzielnie, na globusie lub wpisując je, i nazywasz je, jak chcesz. Widzą je Twoje zaakceptowane kontakty, zaokrąglone do około 50 km; pojawia się też jako anonimowy punkt na mapie publicznej (bez nazwy, zaokrąglone do około 110 km), chyba że się z niej wycofasz. Nigdy adres, nigdy położenie Twojego urządzenia.",
